<?php
declare(strict_types=1);

function languageNames(): array
{
    return ['en' => 'English', 'fr' => 'Français', 'sw' => 'Kiswahili'];
}

function localizedToday(): string
{
    global $language;
    if (($language ?? 'en') === 'en') {
        return date('l, F j, Y');
    }

    $weekdays = $language === 'fr'
        ? ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi']
        : ['Jumapili', 'Jumatatu', 'Jumanne', 'Jumatano', 'Alhamisi', 'Ijumaa', 'Jumamosi'];
    $months = $language === 'fr'
        ? ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre']
        : ['Januari', 'Februari', 'Machi', 'Aprili', 'Mei', 'Juni', 'Julai', 'Agosti', 'Septemba', 'Oktoba', 'Novemba', 'Desemba'];
    $timestamp = time();
    $weekday = $weekdays[(int)date('w', $timestamp)];
    $month = $months[(int)date('n', $timestamp) - 1];
    return $language === 'fr'
        ? $weekday . ' ' . date('j', $timestamp) . ' ' . $month . ' ' . date('Y', $timestamp)
        : $weekday . ', ' . date('j', $timestamp) . ' ' . $month . ' ' . date('Y', $timestamp);
}

function languageSelector(string $page, ?int $recordId = null): void
{
    global $language;
    echo '<form method="get" class="language-switcher"><input type="hidden" name="page" value="' . h($page) . '">';
    if ($recordId !== null) {
        echo '<input type="hidden" name="id" value="' . $recordId . '">';
    }
    echo '<label for="language">Language</label><select id="language" name="lang" onchange="this.form.submit()">';
    foreach (languageNames() as $code => $name) {
        echo '<option value="' . h($code) . '"' . ($language === $code ? ' selected' : '') . '>' . h($name) . '</option>';
    }
    echo '</select><button class="btn btn-light btn-small">Apply</button></form>';
}

