        ],
    ];
    $map = array_merge($translations[$language] ?? [], $additionalTranslations[$language] ?? []);
    $prefixes = [
        'fr' => [
            'Good morning, ' => 'Bonjour, ', 'Good afternoon, ' => 'Bon après-midi, ', 'Good evening, ' => 'Bonsoir, ',
            'Clinic created. Welcome to ' => 'Clinique créée. Bienvenue à ',
