            'Payment receipt · Invoice #' => 'Reçu de paiement · Facture n°',
        ],
        'sw' => [
            'Good morning, ' => 'Habari za asubuhi, ', 'Good afternoon, ' => 'Habari za mchana, ', 'Good evening, ' => 'Habari za jioni, ',
            'Clinic created. Welcome to ' => 'Kliniki imetengenezwa. Karibu ',
            'Administrator account created. Welcome to ' => 'Akaunti ya msimamizi imetengenezwa. Karibu ',
            'Patient registered and checked in. Queue number ' => 'Mgonjwa amesajiliwa na kupokelewa. Nambari ya foleni ',
            'Patient checked in with queue number ' => 'Mgonjwa amepokelewa kwa nambari ya foleni ',
            'Prescription #' => 'Agizo la dawa nambari ',
            'Queue #' => 'Foleni nambari ',
            'Invoice #' => 'Ankara nambari ',
            'Payment receipt · Invoice #' => 'Risiti ya malipo · Ankara nambari ',
        ],
    ][$language] ?? [];
    return preg_replace_callback('/(<[^>]*>|[^<]+)/s', static function (array $match) use ($map, $prefixes): string {
        if (str_starts_with($match[0], '<')) {
            return preg_replace_callback('/\b(placeholder|title|alt|aria-label|data-confirm)="([^"]*)"/', static function (array $attribute) use ($map): string {
                $value = html_entity_decode($attribute[2], ENT_QUOTES | ENT_HTML5, 'UTF-8');
                $translated = $map[$value] ?? null;
                if ($translated === null && preg_match('/^([0-9]+)\s+(.+)$/u', $value, $dynamic) && isset($map[$dynamic[2]])) {
                    $translated = $dynamic[1] . ' ' . $map[$dynamic[2]];
                }
                if ($translated === null && preg_match('/^(.*[0-9])\s+(total|balance|remaining)$/u', $value, $dynamic) && isset($map[$dynamic[2]])) {
                    $translated = $dynamic[1] . ' ' . $map[$dynamic[2]];
                }
                return $attribute[1] . '="' . h($translated ?? $value) . '"';
            }, $match[0]);
        }
        $raw = $match[0];
        $text = html_entity_decode(trim($raw), ENT_QUOTES | ENT_HTML5, 'UTF-8');
        if ($text === '') {
            return $raw;
        }
        preg_match('/^\s*/', $raw, $leading);
        preg_match('/\s*$/', $raw, $trailing);
        if (isset($map[$text])) {
            return ($leading[0] ?? '') . h($map[$text]) . ($trailing[0] ?? '');
        }
        if (preg_match('/^([0-9]+)\s+(.+)$/u', $text, $dynamic) && isset($map[$dynamic[2]])) {
            return ($leading[0] ?? '') . h($dynamic[1] . ' ' . $map[$dynamic[2]]) . ($trailing[0] ?? '');
        }
        if (preg_match('/^(.*[0-9])\s+(total|balance|remaining)$/u', $text, $dynamic) && isset($map[$dynamic[2]])) {
            return ($leading[0] ?? '') . h($dynamic[1] . ' ' . $map[$dynamic[2]]) . ($trailing[0] ?? '');
        }
        foreach ($prefixes as $source => $translated) {
            if (str_starts_with($text, $source)) {
                $suffix = substr($text, strlen($source));
                return ($leading[0] ?? '') . h($translated . $suffix) . ($trailing[0] ?? '');
            }
        }
        return $raw;
    }, $html) ?? $html;
}

function translateText(string $text): string
{
    return html_entity_decode(translateHtml(h($text)), ENT_QUOTES | ENT_HTML5, 'UTF-8');
}
